begin;
select no_plan();
update public.onboarding_settings set enabled=true;
insert into auth.users(id,aud,role,email,email_confirmed_at)
select ('86000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','application-update-'||n||'@example.test',case when n=11 then null else now() end from generate_series(1,14)n;
insert into public.staff_roles(user_id,role) values
 ('86000000-0000-4000-8000-000000000008','membership_reviewer'),
 ('86000000-0000-4000-8000-000000000009','admin'),
 ('86000000-0000-4000-8000-000000000010','super_admin');
insert into public.basic_onboarding_applications(user_id,full_name,email,phone,linkedin_url,date_of_birth,status,submitted_revision,submitted_at)
select id,'Original member',email,'+919876543210','https://linkedin.com/in/original','1990-01-01',
 case right(id::text,2) when '01' then 'approved' when '03' then 'rejected' when '04' then 'revoked' when '05' then 'corrections_requested' when '07' then 'approved' when '09' then 'approved' when '12' then 'approved' else 'pending' end,
 case when right(id::text,2)='06' then null else 1 end,case when right(id::text,2)='06' then null else now() end
from auth.users where id::text like '86000000%' and right(id::text,2) not in ('08','10');
insert into public.onboarding_notice_acceptances(user_id,revision,notice_version)
select user_id,1,'2026-09-26-release-1' from public.basic_onboarding_applications where user_id::text like '86000000%';
insert into public.onboarding_documents(user_id,kind,id_type,object_path,uploaded_at)
select '86000000-0000-4000-8000-000000000002',k,case when k='government_id' then 'pan' end,'update-proof-'||k,now() from unnest(array['photo','government_id'])k;
insert into storage.objects(bucket_id,name) select 'onboarding-documents',object_path from public.onboarding_documents where user_id='86000000-0000-4000-8000-000000000002';
create function pg_temp.update_details(p_revision integer default 1,p_update_revision integer default null,p_name text default 'Changed member',p_birth date default '1990-01-01',p_linkedin text default 'https://linkedin.com/in/original') returns jsonb language sql as $$
 select public.submit_onboarding_update(p_name,p_linkedin,p_birth,'2026-09-26-release-1',p_revision,p_update_revision);
$$;
select ok((select relrowsecurity from pg_class where oid='private.onboarding_updates'::regclass),'proposed updates have RLS');
select ok((select relrowsecurity from pg_class where oid='private.onboarding_update_history'::regclass),'audit history has RLS');
select ok(not has_table_privilege('authenticated','private.onboarding_updates','SELECT,INSERT,UPDATE,DELETE'),'clients cannot access updates directly');
select ok(not has_function_privilege('authenticated','private.require_onboarding_document_update(uuid)','EXECUTE'),'private upload helper is not exposed');
select ok(not has_function_privilege('authenticated','public.finalize_onboarding_document(uuid)','EXECUTE'),'only trusted scanner service can finalize');
set local role anon;
select throws_ok($$select public.get_onboarding_update()$$,'42501',null,'anonymous cannot read proposals');
select throws_ok($$select pg_temp.update_details()$$,'42501',null,'anonymous cannot submit');
set local role authenticated;
select set_config('request.jwt.claim.sub','86000000-0000-4000-8000-000000000011',true);
select throws_ok($$select pg_temp.update_details()$$,'42501',null,'unconfirmed account cannot submit');
select set_config('request.jwt.claim.sub','86000000-0000-4000-8000-000000000006',true);
select throws_ok($$select pg_temp.update_details()$$,'22023',null,'unsubmitted draft uses existing onboarding flow');
select set_config('request.jwt.claim.sub','86000000-0000-4000-8000-000000000001',true);
select is(public.get_onboarding_update(),null::jsonb,'no proposal starts empty');
select throws_ok($$select public.reserve_onboarding_document('photo')$$,'42501',null,'approved account cannot upload without identity proposal');
select throws_ok($$select public.submit_onboarding_update('Changed member','https://linkedin.com/in/original','1990-01-01','old',1)$$,'42501',null,'new proposal needs explicit current notice');
select throws_ok($$select pg_temp.update_details(p_name=>'X')$$,'22023',null,'name validation retained');
select throws_ok($$select pg_temp.update_details(p_linkedin=>'https://linkedin.com/company/test')$$,'22023',null,'personal LinkedIn requirement retained');
select throws_ok($$select pg_temp.update_details(p_birth=>current_date)$$,'22023',null,'minimum age retained');
select throws_ok($$select pg_temp.update_details(p_name=>'Original member')$$,'22023',null,'no-change proposals rejected');
select throws_ok($$select pg_temp.update_details(p_revision=>2)$$,'40001',null,'stale active application revision rejected');
select set_config('test.approved_update',pg_temp.update_details()->>'id',true);
select is(public.get_onboarding_update()->>'status','pending','approved account proposes changes for review');
select is(public.get_onboarding_update()->>'identity_changed','true','name change marked as identity change');
select is(public.get_onboarding_update()->>'needs_documents','true','expired or missing evidence requires replacement');
select is((select full_name from public.basic_onboarding_applications where user_id=auth.uid()),'Original member','proposal does not overwrite approved name');
select is((select status from public.basic_onboarding_applications where user_id=auth.uid()),'approved','proposal keeps identity approval active');
select is((select revision from public.basic_onboarding_applications where user_id=auth.uid()),1,'proposal leaves active revision unchanged');
select throws_ok($$select pg_temp.update_details()$$,'40001',null,'duplicate pending proposal requires expected update revision');
select is(pg_temp.update_details(p_update_revision=>1,p_name=>'Changed again')->>'revision','2','owner may replace proposed values using CAS');
select throws_ok($$select pg_temp.update_details(p_update_revision=>1)$$,'40001',null,'stale proposal save rejected');
select ok(public.onboarding_document_upload_allowed(),'approved identity proposal permits replacement evidence');
select lives_ok($$select public.reserve_onboarding_document('photo')$$,'photo reservation allowed for current identity proposal');
select lives_ok($$select public.reserve_onboarding_document('government_id','pan')$$,'ID reservation allowed for current identity proposal');
select throws_ok($$select public.reserve_onboarding_document('photo')$$,'23505',null,'active evidence slot cannot be overwritten');
select set_config('request.jwt.claim.sub','86000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.get_onboarding_update('86000000-0000-4000-8000-000000000001')$$,'42501',null,'other member cannot inspect proposal');
select throws_ok($$select public.withdraw_onboarding_update(current_setting('test.approved_update')::uuid,2)$$,'42501',null,'other member cannot withdraw');
select throws_ok($$select public.list_onboarding_updates()$$,'42501',null,'ordinary member cannot enumerate proposals');
select set_config('test.pending_update',pg_temp.update_details()->>'id',true);
select is((select submitted_revision from public.basic_onboarding_applications where user_id=auth.uid()),1,'proposing does not revoke existing submission');
select set_config('request.jwt.claim.sub','86000000-0000-4000-8000-000000000008',true);
select is(public.list_onboarding_updates()->>'total','2','membership staff sees pending proposed changes');
select throws_ok($$select public.list_onboarding_updates('all')$$,'42501',null,'staff cannot enumerate closed historical proposals');
select ok(public.can_review_onboarding_update('86000000-0000-4000-8000-000000000001'),'staff can read pending identity update evidence');
select is((select count(*)::integer from public.onboarding_documents where user_id='86000000-0000-4000-8000-000000000001'),2,'document RLS grants scoped update evidence');
select is((select count(*)::integer from public.basic_onboarding_applications where user_id='86000000-0000-4000-8000-000000000001'),1,'Staff can inspect active details only while independent update is pending');
select ok(not public.can_review_basic_application('86000000-0000-4000-8000-000000000001'),'proposal does not expand original approval authority');
select throws_ok($$select public.review_onboarding_update(current_setting('test.approved_update')::uuid,2,'rejected','Reject for test')$$,'42501',null,'staff cannot reject');
select throws_ok($$select public.review_onboarding_update(current_setting('test.approved_update')::uuid,1,'approved','Reviewed identity details')$$,'40001',null,'stale staff review rejected');
select throws_ok($$select public.review_onboarding_update(current_setting('test.approved_update')::uuid,2,'approved','Reviewed identity details')$$,'22023',null,'reservations without scanned uploads cannot approve identity changes');
select throws_ok($$select public.review_basic_onboarding('86000000-0000-4000-8000-000000000002','approved',null,null,null,1)$$,'22023','Proposed changes must be resolved before identity approval','otherwise complete original cannot be approved while member corrects it');
select is(public.review_onboarding_update(current_setting('test.pending_update')::uuid,1,'approved','Reviewed corrected details')->>'status','approved','staff may approve pending application detail correction');
reset role;
select is((select status from public.basic_onboarding_applications where user_id='86000000-0000-4000-8000-000000000002'),'pending','details approval does not approve membership');
select is((select revision from public.basic_onboarding_applications where user_id='86000000-0000-4000-8000-000000000002'),2,'accepted details invalidate old application revision');
select is((select submitted_revision from public.basic_onboarding_applications where user_id='86000000-0000-4000-8000-000000000002'),null::integer,'new pending details need explicit final submission');
select is((select notice_version from public.onboarding_notice_acceptances where user_id='86000000-0000-4000-8000-000000000002' and revision=2),'2026-09-26-release-1','proposal consent bound to accepted revision');
insert into storage.objects(bucket_id,name) select 'onboarding-documents',object_path from public.onboarding_documents where user_id='86000000-0000-4000-8000-000000000001';
set local role service_role;
select lives_ok($$select public.finalize_onboarding_document(id) from public.onboarding_documents where user_id='86000000-0000-4000-8000-000000000001'$$,'scanner finalizes approved proposal uploads');
reset role;
select ok((select bool_and(expires_at<=now()+interval '30 days 1 minute') from public.onboarding_documents where user_id='86000000-0000-4000-8000-000000000001'),'unconsented documents keep bounded original retention');
