select set_config('request.jwt.claim.sub','86000000-0000-4000-8000-000000000008',true);
select is(public.review_onboarding_update(current_setting('test.approved_update')::uuid,2,'approved','Compared changed name against ID')->>'status','approved','independent staff applies evidenced identity change');
select is(public.get_onboarding_update('86000000-0000-4000-8000-000000000001'),null::jsonb,'staff loses closed proposal read access');
select is((select count(*)::integer from public.onboarding_documents where user_id='86000000-0000-4000-8000-000000000001'),0,'staff evidence access closes after review');
select is((select count(*)::integer from public.basic_onboarding_applications where user_id='86000000-0000-4000-8000-000000000001'),0,'staff active-details access closes after review');
reset role;
