select is((select status from public.basic_onboarding_applications where user_id='86000000-0000-4000-8000-000000000001'),'approved','accepted approved update retains approval');
select is((select phone from public.basic_onboarding_applications where user_id='86000000-0000-4000-8000-000000000001'),'+919876543210','update cannot overwrite verified mobile');
select is((select count(*)::integer from private.onboarding_update_history where update_id=current_setting('test.approved_update')::uuid),3,'every proposal revision and review has immutable audit');
set local role authenticated;
